{"challengeId": "dupes", "answer": "function firstDuplicate(nums) {
  const seen = new Set();
  for (const n of nums) {
    if (seen.has(n)) return n;
    seen.add(n);
  }
  return null;
}"}

{"challengeId": "dupes", "answer": "function firstDuplicate(nums) {
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === nums[nums.length - 1]) return nums[i];
  }
  return null;
}"}

{"challengeId": "reverse", "answer": "function reverseInPlace(arr) {
  let left = 0, right = arr.length - 1;
  while (left < right) {
    [arr[left], arr[right]] = [arr[right], arr[left]];
    left++;
    right--;
  }
  return arr;
}"}
